<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\SnippetAssetContentVO;

trait SnippetAssetContentAccessor
{
    private SnippetAssetContentVO $_content;
    public function getContent(): string
    {
        return $this->_content->value();
    }
    public function content(): SnippetAssetContentVO
    {
        return $this->_content;
    }
    public function isContentChanged(?self $original = null): bool
    {
        return !$this->_content->equals($original?->_content);
    }
    public function withContent(SnippetAssetContentVO|string $content): self
    {
        $copy = clone $this;
        $copy->_content = SnippetAssetContentVO::from($content);
        return $copy;
    }
}
